// Applies the SQL migrations in ./drizzle (generated by `npm run db:generate`)
// to the configured database, in order, recording each in __migrations.
// Runs automatically before `npm run dev`; for production run:
//   npm run db:migrate
import { readFileSync } from "node:fs";
import path from "node:path";
import { loadEnv, openDatabase, redact, ROOT } from "./lib/db.mjs";

loadEnv();

const folder = path.join(ROOT, "drizzle");
const journal = JSON.parse(readFileSync(path.join(folder, "meta", "_journal.json"), "utf8"));

let db;
try {
  db = openDatabase();
  await db.exec(
    "CREATE TABLE IF NOT EXISTS __migrations (tag TEXT PRIMARY KEY, applied_at INTEGER NOT NULL)",
  );
  const applied = new Set((await db.query("SELECT tag FROM __migrations")).map((r) => r.tag));

  let count = 0;
  for (const entry of journal.entries) {
    if (applied.has(entry.tag)) continue;
    const sql = readFileSync(path.join(folder, `${entry.tag}.sql`), "utf8");
    const statements = sql.split("--> statement-breakpoint").map((s) => s.trim()).filter(Boolean);
    await db.exec(`BEGIN;\n${statements.map((s) => (s.endsWith(";") ? s : `${s};`)).join("\n")}\nCOMMIT;`);
    await db.run("INSERT INTO __migrations (tag, applied_at) VALUES (?, ?)", [entry.tag, Date.now()]);
    console.log(`[db] applied ${entry.tag}`);
    count++;
  }
  console.log(`[db] ${count ? `${count} migration(s) applied` : "already up to date"} (${redact(db.url)})`);
} catch (error) {
  console.error(`[db] migration failed: ${error instanceof Error ? error.message : error}`);
  process.exitCode = 1;
} finally {
  db?.close();
}
